CREATE TABLE users(id TEXT PRIMARY KEY,issuer TEXT NOT NULL,subject TEXT NOT NULL,UNIQUE(issuer,subject));
CREATE TABLE accounts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),metadata TEXT NOT NULL,credential BYTEA NOT NULL,connected_at TEXT);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at BIGINT NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE oidc_flows(state_hash TEXT PRIMARY KEY,nonce TEXT NOT NULL,verifier TEXT NOT NULL,expires_at BIGINT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE push_endpoints(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),document TEXT NOT NULL,UNIQUE(user_id,id));
CREATE TABLE search_cursors(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),document TEXT NOT NULL,expires_at BIGINT NOT NULL);
CREATE INDEX search_cursor_expiry ON search_cursors(expires_at);
CREATE TABLE removed_accounts(id TEXT PRIMARY KEY);
CREATE TABLE local_login(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES users(id),username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,is_owner BIGINT NOT NULL DEFAULT 0 CHECK(is_owner IN (0,1)));
CREATE TABLE login_throttle(id BIGINT PRIMARY KEY CHECK(id=1),window_start BIGINT NOT NULL,attempts BIGINT NOT NULL);
CREATE TABLE local_invitations(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,created_by TEXT NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL);
CREATE INDEX invitation_expiry ON local_invitations(expires_at);
CREATE TABLE auth_attempts(bucket TEXT PRIMARY KEY,window_start BIGINT NOT NULL,attempts BIGINT NOT NULL);
CREATE TABLE gmail_oauth_flows(state_hash TEXT PRIMARY KEY,session_hash TEXT NOT NULL REFERENCES sessions(token_hash) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),verifier TEXT NOT NULL,email TEXT NOT NULL,display_name TEXT NOT NULL,account_id TEXT,expires_at BIGINT NOT NULL);
CREATE TABLE mail_rules(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),preset TEXT NOT NULL,sender TEXT NOT NULL,document TEXT NOT NULL,UNIQUE(user_id,preset,sender));
CREATE TABLE control_locks(name TEXT PRIMARY KEY,revision BIGINT NOT NULL DEFAULT 0);
INSERT INTO control_locks(name) VALUES('auth');
